        street = {site: sites_data[site]['street'] for site in sites}
        desired_time = {site: sites_data[site]['desiredtime'] for site in sites}
        value = {site: sites_data[site]['value'] for site in sites}
        begin = {site: sites_data[site]['beginhour'] * 60 for site in sites}
        end = {site: sites_data[site]['endhour'] * 60 for site in sites}

